-- Loan_Model_Monthly: the Model sheet's month-by-month blocks (for the cash-flow charts), one row per
-- loan and series, months in m01..m36:
--   CF$            t-24 to t-01     Model!XD:YA
--   Perf CF        month 1-36       Model!ABM:ACV
--   Payoff CF      month 1-36       Model!AED:AFM
--   REO CF         month 1-36       Model!AGZ:AII
--   NPL CF         month 1-36       Model!AJO:AKX
--   CUSTOM CF      month 1-36       Model!ALV:ANE
--   MATURING PERF CF month 1-36       Model!AOF:APO
--   GNMA POOL CF   month 1-36       Model!AQZ:ASI
--   GNMA CLAIM CF  month 1-36       Model!ATK:AUT
--   Amo Pd #       t+1 to t+36      Model!AXX:AZG
--   Rate pct       t+1 to t+36      Model!AZJ:BAS
--   P&I amount     t+1 to t+36      Model!BAV:BCE
--   Interest $     t+1 to t+36      Model!BCH:BDQ
--   Principal $    t+1 to t+36      Model!BDT:BFC
--   Balance $      t+1 to t+36      Model!BFF:BGO
--   Prin Amo $     t+1 to t+36      Model!BHO:BIX
IF OBJECT_ID('dbo.Loan_Model_Monthly') IS NULL
CREATE TABLE dbo.Loan_Model_Monthly (
  [Table_Type] NVARCHAR(50) NOT NULL DEFAULT N'BPL',
  [loan_id] NVARCHAR(50) NOT NULL,
  [series] NVARCHAR(50) NOT NULL,
  [periods] NVARCHAR(50) NULL,
  [m01] DECIMAL(28,10) NULL,
  [m02] DECIMAL(28,10) NULL,
  [m03] DECIMAL(28,10) NULL,
  [m04] DECIMAL(28,10) NULL,
  [m05] DECIMAL(28,10) NULL,
  [m06] DECIMAL(28,10) NULL,
  [m07] DECIMAL(28,10) NULL,
  [m08] DECIMAL(28,10) NULL,
  [m09] DECIMAL(28,10) NULL,
  [m10] DECIMAL(28,10) NULL,
  [m11] DECIMAL(28,10) NULL,
  [m12] DECIMAL(28,10) NULL,
  [m13] DECIMAL(28,10) NULL,
  [m14] DECIMAL(28,10) NULL,
  [m15] DECIMAL(28,10) NULL,
  [m16] DECIMAL(28,10) NULL,
  [m17] DECIMAL(28,10) NULL,
  [m18] DECIMAL(28,10) NULL,
  [m19] DECIMAL(28,10) NULL,
  [m20] DECIMAL(28,10) NULL,
  [m21] DECIMAL(28,10) NULL,
  [m22] DECIMAL(28,10) NULL,
  [m23] DECIMAL(28,10) NULL,
  [m24] DECIMAL(28,10) NULL,
  [m25] DECIMAL(28,10) NULL,
  [m26] DECIMAL(28,10) NULL,
  [m27] DECIMAL(28,10) NULL,
  [m28] DECIMAL(28,10) NULL,
  [m29] DECIMAL(28,10) NULL,
  [m30] DECIMAL(28,10) NULL,
  [m31] DECIMAL(28,10) NULL,
  [m32] DECIMAL(28,10) NULL,
  [m33] DECIMAL(28,10) NULL,
  [m34] DECIMAL(28,10) NULL,
  [m35] DECIMAL(28,10) NULL,
  [m36] DECIMAL(28,10) NULL,
  [File_Name] NVARCHAR(200) NOT NULL DEFAULT N'Pacific Private Money',
  CONSTRAINT PK_Loan_Model_Monthly PRIMARY KEY ([loan_id], [series])
);
GO

-- LoanChanges: one row per edited value in the app (written by the app, read back to replay edits).
-- Column_Name is the Loan_Model column. A reset back to the model's own value is logged with
-- New_Value "<value> (reset)".
IF OBJECT_ID('dbo.LoanChanges') IS NULL
CREATE TABLE dbo.LoanChanges (
  [Table_Type] NVARCHAR(50) NOT NULL DEFAULT N'BPL',
  [File_Name] NVARCHAR(200) NOT NULL,
  [Loan_Id] NVARCHAR(50) NOT NULL,
  [Column_Name] NVARCHAR(128) NOT NULL,
  [Old_Value] NVARCHAR(400) NULL,
  [New_Value] NVARCHAR(400) NULL,
  [User_mail] NVARCHAR(320) NOT NULL,
  [Changed_On] DATETIME2 NOT NULL,
  CONSTRAINT PK_LoanChanges PRIMARY KEY ([File_Name], [Loan_Id], [Column_Name], [Changed_On])
);
GO
